journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c08_started }
	OR = {
		AND = { c:DMG ?= this OR = { ywc_c08_case_ready_dmg = yes var:ywc_c08_case_open ?= 1 } }
		AND = { c:NMG ?= this var:ywc_c08_case_open ?= 1 }
		AND = { OR = { c:MHG ?= this c:SHU ?= this c:JHG ?= this c:LAN ?= this c:WBK ?= this } var:ywc_c08_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c08_started }
	OR = {
		AND = { c:DMG ?= this OR = { ywc_c08_case_ready_dmg = yes var:ywc_c08_case_open ?= 1 } }
		AND = { c:NMG ?= this var:ywc_c08_case_open ?= 1 }
		AND = { OR = { c:MHG ?= this c:SHU ?= this c:JHG ?= this c:LAN ?= this c:WBK ?= this } var:ywc_c08_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c08_started } }
		set_variable = { name = ywc_c08_started value = 1 }
		set_variable = { name = ywc_c08_popup_epoch value = 0 }
		set_variable = { name = ywc_c08_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c08_popup_epoch } } set_variable = { name = ywc_c08_popup_epoch value = 0 } }
	if = { limit = { c:DMG ?= this NOT = { has_variable = ywc_c08_role } } set_variable = { name = ywc_c08_role value = 1 } }
	if = { limit = { c:NMG ?= this NOT = { has_variable = ywc_c08_role } } set_variable = { name = ywc_c08_role value = 2 } }
	if = { limit = { OR = { c:MHG ?= this c:SHU ?= this c:JHG ?= this c:LAN ?= this c:WBK ?= this } NOT = { has_variable = ywc_c08_role } } set_variable = { name = ywc_c08_role value = 3 } }
	if = { limit = { c:DMG ?= this NOT = { has_variable = ywc_c08_stage } }
		set_variable = { name = ywc_c08_case_open value = 1 }
		set_variable = { name = ywc_c08_stage value = 1700 }
		set_variable = { name = ywc_c08_pending value = 1700 }
	}
}
on_monthly_pulse = {
	effect = {
# DMG awaits the external note; a dead or withdrawn claimant proceeds unilaterally.
	if = { limit = { c:DMG ?= this var:ywc_c08_stage ?= 1712 }
		change_variable = { name = ywc_c08_wait_age add = 1 }
		if = { limit = { ywc_c08_nmg_note_moot = yes } ywc_c08_after_ext_note = yes }
		else_if = { limit = { OR = { ywc_c08_nmg_note_recorded = yes var:ywc_c08_wait_age >= 12 } } ywc_c08_after_ext_note = yes }
	}
# Orphan close: the claimant or a partner holding an early stage loses its counterpart.
	if = { limit = {
		OR = { c:NMG ?= this OR = { c:MHG ?= this c:SHU ?= this c:JHG ?= this c:LAN ?= this c:WBK ?= this } }
		OR = { var:ywc_c08_stage ?= 1702 var:ywc_c08_stage ?= 1711 }
		ywc_c08_initiator_gone = yes
	}
		ywc_c08_close_no_talks = yes
	}
# Deliveries bound to journal 1.
	if = { limit = { ywc_c08_dmg_delivery_1700 = yes } trigger_event = { id = ywc_crisis.1700 } }
	if = { limit = { ywc_c08_dmg_delivery_1701 = yes } trigger_event = { id = ywc_crisis.1701 } }
	if = { limit = { ywc_c08_nmg_delivery_1702 = yes } trigger_event = { id = ywc_crisis.1702 } }
	if = { limit = { ywc_c08_dmg_delivery_1703 = yes } trigger_event = { id = ywc_crisis.1703 } }
	if = { limit = { ywc_c08_partner_delivery_1711 = yes } trigger_event = { id = ywc_crisis.1711 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c08_program_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c08_started
	var:ywc_c08_program_open ?= 1
	OR = { c:DMG ?= this c:NMG ?= this }
	NOT = { has_variable = ywc_c08_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c08_popup_epoch } } set_variable = { name = ywc_c08_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
# DMG awaits the conditions answer; a dead, withdrawn or silent claimant opens the reply anyway.
	if = { limit = { c:DMG ?= this var:ywc_c08_stage ?= 1715 }
		change_variable = { name = ywc_c08_wait_age add = 1 }
		if = { limit = { ywc_c08_nmg_conditions_moot = yes } ywc_c08_skip_conditions = yes }
		else_if = { limit = { OR = { ywc_c08_nmg_conditions_recorded = yes var:ywc_c08_wait_age >= 24 } } ywc_c08_open_condition_reply = yes }
	}
# Orphan close: the claimant at its own execution stages loses its counterpart.
	if = { limit = {
		c:NMG ?= this
		OR = { var:ywc_c08_stage ?= 1704 var:ywc_c08_stage ?= 1707 }
		ywc_c08_dmg_gone_or_closed = yes
	}
		ywc_c08_close_no_talks = yes
	}
# Deliveries bound to journal 2.
	if = { limit = { ywc_c08_dmg_delivery_1704 = yes } trigger_event = { id = ywc_crisis.1704 } }
	if = { limit = { ywc_c08_nmg_delivery_1704 = yes } trigger_event = { id = ywc_crisis.1704 } }
	if = { limit = { ywc_c08_dmg_delivery_1705 = yes } trigger_event = { id = ywc_crisis.1705 } }
	if = { limit = { ywc_c08_dmg_delivery_1706 = yes } trigger_event = { id = ywc_crisis.1706 } }
	if = { limit = { ywc_c08_nmg_delivery_1707 = yes } trigger_event = { id = ywc_crisis.1707 } }
	if = { limit = { ywc_c08_dmg_delivery_1716 = yes } trigger_event = { id = ywc_crisis.1707 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c08_review_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c08_started
	var:ywc_c08_review_open ?= 1
	OR = { c:DMG ?= this c:NMG ?= this }
	NOT = { has_variable = ywc_c08_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c08_popup_epoch } } set_variable = { name = ywc_c08_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
# NMG awaits the forum proposal; a dead or closed jurisdiction closes the talks.
	if = { limit = { c:NMG ?= this var:ywc_c08_stage ?= 1718 }
		change_variable = { name = ywc_c08_wait_age add = 1 }
		if = { limit = { ywc_c08_dmg_gone_or_closed = yes } ywc_c08_close_no_talks = yes }
		else_if = { limit = { OR = { ywc_c08_dmg_forum_proposed = yes var:ywc_c08_wait_age >= 24 } } ywc_c08_open_nmg_renegotiation = yes }
	}
# NMG has accepted on record and awaits the jurisdiction's settlement.
	if = { limit = { c:NMG ?= this var:ywc_c08_stage ?= 1721 }
		change_variable = { name = ywc_c08_wait_age add = 1 }
		if = { limit = { ywc_c08_dmg_gone_or_closed = yes } ywc_c08_close_no_talks = yes }
		else_if = { limit = { var:ywc_c08_wait_age >= 36 } ywc_c08_close_status_quo = yes }
	}
# Mirror: once the jurisdiction settles, the acceptance on record adopts its outcome.
	if = { limit = {
		c:NMG ?= this
		has_variable = ywc_c08_nmg_confirm
		NOT = { has_variable = ywc_c08_outcome }
		ywc_c08_dmg_settled = yes
	}
		ywc_c08_nmg_mirror_settle = yes
	}
# Orphan close for the claimant inside the renegotiation and settlement rounds.
	if = { limit = {
		c:NMG ?= this
		OR = { var:ywc_c08_stage ?= 1709 var:ywc_c08_stage ?= 1710 }
		ywc_c08_dmg_gone_or_closed = yes
	}
		ywc_c08_close_no_talks = yes
	}
# Deliveries bound to journal 3.
	if = { limit = { ywc_c08_dmg_delivery_1708 = yes } trigger_event = { id = ywc_crisis.1708 } }
	if = { limit = { ywc_c08_dmg_delivery_1709 = yes } trigger_event = { id = ywc_crisis.1709 } }
	if = { limit = { ywc_c08_nmg_delivery_1709 = yes } trigger_event = { id = ywc_crisis.1709 } }
	if = { limit = { ywc_c08_dmg_delivery_1710 = yes } trigger_event = { id = ywc_crisis.1710 } }
	if = { limit = { ywc_c08_nmg_delivery_1710 = yes } trigger_event = { id = ywc_crisis.1710 } }
	if = { limit = { ywc_c08_dmg_delivery_1711 = yes } trigger_event = { id = ywc_crisis.1711 } }
	}
}
}
